function Prediction() {
  const navigate = useNavigate();
  const inputRef = useRef(null);

  const [language, setLanguage] = useState('en');
  const [darkMode, setDarkMode] = useState(true);
  const [inputValue, setInputValue] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentStep, setCurrentStep] = useState(0);
  const [waitingForAdvice, setWaitingForAdvice] = useState(false);
  const [adviceStage, setAdviceStage] = useState(0);
  const [userData, setUserData] = useState({});

  const t = translations[language];

  // Add a bot message to chat history
  function addBotMessage(text) {
    setChatHistory((prev) => [...prev, { sender: 'bot', text }]);
  }

  // Add a user message to chat history
  function addUserMessage(text) {
    setChatHistory((prev) => [...prev, { sender: 'user', text }]);
  }

  // On component mount, greet user
  useEffect(() => {
    addBotMessage(t.startMessage1);
    setTimeout(() => {
      addBotMessage(t.startMessage2);
      addBotMessage(t.questions[0]);
    }, 1500);
  }, [language]);

  useEffect(() => {
    inputRef.current?.focus();
  }, [chatHistory]);

  // Validation helpers
  function validateNumber(input, min, max) {
    const num = Number(input);
    return !isNaN(num) && num >= min && num <= max;
  }

  function validateYesNo(input) {
    return [t.yes.toLowerCase(), t.no.toLowerCase()].includes(input.toLowerCase());
  }

  function normalizeYesNo(input) {
    return input.toLowerCase() === t.yes.toLowerCase();
  }

  function validateGender(input) {
    return t.genderOptions.map(g => g.toLowerCase()).includes(input.toLowerCase());
  }

  function normalizeGender(input) {
    // Normalize to first letter uppercase
    const found = t.genderOptions.find(g => g.toLowerCase() === input.toLowerCase());
    return found || input;
  }

  function validateSmoking(input) {
    return t.smokingOptions.map(s => s.toLowerCase()).includes(input.toLowerCase());
  }

  function normalizeSmoking(input) {
    const found = t.smokingOptions.find(s => s.toLowerCase() === input.toLowerCase());
    return found || input;
  }

  // Calculate risk dummy function
  function calculateRisk(data) {
    const base = 10;
    const risk = base +
      (data.age || 0) * 0.1 +
      (data.bmi || 0) * 0.2 +
      (data.hba1c || 0) * 0.5 +
      (data.glucose || 0) * 0.1 +
      (data.hypertension ? 5 : 0) +
      (data.heartDisease ? 5 : 0);
    return Math.min(100, Math.round(risk));
  }

  // Handle form submission and chat progression
  function handleSubmit(e) {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const trimmedInput = inputValue.trim();
    addUserMessage(trimmedInput);

    if (waitingForAdvice) {
      // User answers yes/no to advice question
      if (!validateYesNo(trimmedInput)) {
        addBotMessage(t.pleaseYesNo);
      } else {
        const wantsAdvice = normalizeYesNo(trimmedInput);
        if (wantsAdvice) {
          addBotMessage(t.okayMoreAdvice);
          setWaitingForAdvice(false);
          provideAdvice();
        } else {
          addBotMessage(t.alrightAdviceDeclined);
          setWaitingForAdvice(false);
          setAdviceStage(0);
        }
      }
      setInputValue('');
      return;
    }

    // Handle regular questions flow
    switch (currentStep) {
      case 0: // Age
        if (!validateNumber(trimmedInput, 1, 120)) {
          addBotMessage(t.enterNumberBetween(1, 120));
        } else {
          setUserData((u) => ({ ...u, age: Number(trimmedInput) }));
          addBotMessage(t.questions[1]);
          setCurrentStep(1);
        }
        break;

      case 1: // Gender
        if (!validateGender(trimmedInput)) {
          addBotMessage(t.pleaseChoose(t.genderOptions));
        } else {
          setUserData((u) => ({ ...u, gender: normalizeGender(trimmedInput) }));
          addBotMessage(t.questions[2]);
          setCurrentStep(2);
        }
        break;

      case 2: // BMI
        if (!validateNumber(trimmedInput, 10, 70)) {
          addBotMessage(t.enterNumberBetween(10, 70));
        } else {
          setUserData((u) => ({ ...u, bmi: Number(trimmedInput) }));
          addBotMessage(t.questions[3]);
          setCurrentStep(3);
        }
        break;

      case 3: // HbA1c
        if (!validateNumber(trimmedInput, 3, 15)) {
          addBotMessage(t.enterNumberBetween(3, 15));
        } else {
          setUserData((u) => ({ ...u, hba1c: Number(trimmedInput) }));
          addBotMessage(t.questions[4]);
          setCurrentStep(4);
        }
        break;

      case 4: // Glucose
        if (!validateNumber(trimmedInput, 50, 500)) {
          addBotMessage(t.enterNumberBetween(50, 500));
        } else {
          setUserData((u) => ({ ...u, glucose: Number(trimmedInput) }));
          addBotMessage(t.questions[5]);
          setCurrentStep(5);
        }
        break;

      case 5: // Hypertension
        if (!validateYesNo(trimmedInput)) {
          addBotMessage(t.pleaseYesNo);
        } else {
          setUserData((u) => ({ ...u, hypertension: normalizeYesNo(trimmedInput) }));
          addBotMessage(t.questions[6]);
          setCurrentStep(6);
        }
        break;

      case 6: // Heart disease
        if (!validateYesNo(trimmedInput)) {
          addBotMessage(t.pleaseYesNo);
        } else {
          setUserData((u) => ({ ...u, heartDisease: normalizeYesNo(trimmedInput) }));
          addBotMessage(t.questions[7]);
          setCurrentStep(7);
        }
        break;

      case 7: // Smoking history
        if (!validateSmoking(trimmedInput)) {
          addBotMessage(t.pleaseChoose(t.smokingOptions));
        } else {
          setUserData((u) => ({ ...u, smoking: normalizeSmoking(trimmedInput) }));
          addBotMessage(t.thankYou);

          // Calculate risk after small delay
          setTimeout(() => {
            const risk = calculateRisk(userData);
            addBotMessage(t.riskResult(risk));

            setTimeout(() => {
              addBotMessage(t.adviceQuestion);
              setWaitingForAdvice(true);
            }, 1500);
          }, 1500);

          setCurrentStep(currentStep + 1);
        }
        break;

      default:
        addBotMessage(t.allAdviceDone);
        break;
    }

    setInputValue('');
  }

  // Provide advice messages in stages
  function provideAdvice() {
    const allAdvice = [
      { title: t.generalAdviceTitle, list: t.generalAdvice },
      { title: t.dietAdviceTitle, list: t.dietAdvice },
      { title: t.warningSignsTitle, list: t.warningSigns },
    ];

    if (adviceStage < allAdvice.length) {
      const advice = allAdvice[adviceStage];
      addBotMessage(advice.title);
      advice.list.forEach((msg) => addBotMessage(msg));

      setAdviceStage(adviceStage + 1);

      // Ask user if want more advice after current advice block
      setTimeout(() => {
        addBotMessage(t.adviceQuestion);
        setWaitingForAdvice(true);
      }, 2000);
    } else {
      addBotMessage(t.allAdviceDone);
      addBotMessage(t.consultDoctor);
      setWaitingForAdvice(false);
      setAdviceStage(0);
    }
  }

  return (
    <div
      className={`prediction-container ${darkMode ? 'dark' : 'light'}`}
      style={{ backgroundImage: `url(${backgroundImage})` }}
    >
      <header className="header">
        <nav>
          <button onClick={() => navigate('/')}>{t.home}</button>
          <button onClick={() => navigate('/visualization')}>{t.visualization}</button>
        </nav>
        <div className="language-switcher">
          <label htmlFor="language-select">{t.languageLabel}</label>
          <select
            id="language-select"
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
          >
            <option value="en">English</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>
        </div>
        <button className="dark-mode-toggle" onClick={() => setDarkMode(!darkMode)}>
          <img
            src={darkMode ? sunIcon : moonIcon}
            alt={darkMode ? t.darkModeOff : t.darkModeOn}
            width={24}
            height={24}
          />
        </button>
      </header>

      <main className="chat-container" role="main" aria-live="polite" aria-atomic="false">
        <ul className="chat-history">
          {chatHistory.map((msg, i) => (
            <li key={i} className={`chat-message ${msg.sender}`}>
              {msg.text}
            </li>
          ))}
          {waitingForAdvice && <li className="chat-message bot typing">{t.typing}</li>}
        </ul>

        <form className="input-form" onSubmit={handleSubmit}>
          <input
            type="text"
            ref={inputRef}
            placeholder={waitingForAdvice ? t.adviceQuestion : t.questions[currentStep] || ''}
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            aria-label="Chat input"
            autoComplete="off"
          />
          <button type="submit" aria-label="Send">
            <img src={sendIcon} alt="Send" width={20} height={20} />
          </button>
        </form>
      </main>
    </div>
  );
}

export default Prediction;
